/**
 * The relay's performance gates (#194), deterministic and fast enough for CI.
 *
 * Each runs a scenario of `test/bench/relaySim.ts` on a virtual clock with a fixed seed, so the
 * numbers are exactly the same on every machine and a failure is a change in the code, not in the
 * runner. The thresholds are the measured values with headroom (the table is in
 * `docs/relay-benchmark-results.md`, regenerated by `npm run bench:relay`); tighten them when the
 * results improve, and say why in the commit when they have to move the other way.
 */
import { describe, expect, it } from 'vitest';
import { PROFILES, runScenario, type ScenarioResult } from './bench/relaySim';
import { BURST, scenario } from './bench/relayReport';

const base = { clicks: 30, durationMs: 120_000, seed: 20261019 } as const;
const relay = { ...base, transport: 'relay' as const, profile: PROFILES.relayGood };
const lan = { ...base, transport: 'lan' as const, profile: PROFILES.lan };

/** A scenario's result without the one field that is real time. */
const stable = (r: ScenarioResult) => ({ ...r, cpuMs: 0 });

describe('relay benchmark model', () => {
  it('is deterministic: the same seed gives the same numbers', async () => {
    const s = scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active' });
    expect(stable(await runScenario(s))).toEqual(stable(await runScenario(s)));
  });

  it('a different seed moves the jitter and nothing structural', async () => {
    const a = await runScenario(scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active' }));
    const b = await runScenario(scenario({ ...relay, seed: 7, sessions: 5, conversation: 'large', mode: 'active' }));
    expect(b.clicks).toBe(a.clicks);
    expect(b.firstMs.p50).not.toBe(a.firstMs.p50);
    expect(Math.abs(b.firstMs.p50 - a.firstMs.p50)).toBeLessThan(40);
  });
});

describe('LAN baseline', () => {
  it('opens a large conversation within a frame or two of the daemon reading it', async () => {
    const r = await runScenario(scenario({ ...lan, sessions: 20, conversation: 'large', mode: 'active' }));
    expect(r.clicks).toBe(30);
    expect(r.firstMs.p95).toBeLessThanOrEqual(200);
    expect(r.commandMs.p95).toBeLessThanOrEqual(10);
  });
});

describe('remote click-to-content (good link: 40 ms to Supabase, 10 ms jitter)', () => {
  for (const sessions of [1, 5, 20] as const) {
    for (const conversation of ['small', 'large'] as const) {
      it(`${sessions} active sessions, ${conversation} conversation`, async () => {
        const r = await runScenario(scenario({ ...relay, sessions, conversation, mode: 'active' }));
        expect(r.clicks).toBe(30);
        expect(r.reconnects).toBe(0);
        // Up (160 ms round trip's half), the daemon, the batch in flight, down: a bit over half a second at the tail.
        expect(r.firstMs.p50).toBeLessThanOrEqual(350);
        expect(r.firstMs.p95).toBeLessThanOrEqual(560);
        expect(r.interactiveMs.p95).toBeLessThanOrEqual(r.firstMs.p95 + 5);
        // Wire cost per click, snapshots and streaming included: well under a megabyte a minute at this load.
        expect(r.bytesDown).toBeLessThanOrEqual(2 * 1024 * 1024);
      });
    }
  }

  it('a large conversation sends the recent window, not the transcript', async () => {
    const remote = await runScenario(scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active' }));
    const local = await runScenario(scenario({ ...lan, sessions: 5, conversation: 'large', mode: 'active' }));
    // 30 clicks: the LAN tab is sent 300 blocks uncompressed, the remote one 60, deflated.
    expect(remote.bytesDown * 5).toBeLessThan(local.bytesDown);
  });

  it('an idle or hidden tab sends no repeated snapshots', async () => {
    for (const mode of ['idle', 'background'] as const) {
      const r = await runScenario(scenario({ ...relay, sessions: 20, conversation: 'large', mode, clicks: 0, commands: 0 }));
      expect(r.snapshotsBuilt).toBeGreaterThan(100);
      expect(r.snapshotsSent).toBeLessThanOrEqual(1);
    }
  });

  it('an active table is sent at most every five seconds', async () => {
    const r = await runScenario(scenario({ ...relay, sessions: 20, conversation: 'small', mode: 'active', clicks: 0, commands: 0 }));
    // The model runs on for 50 s past `durationMs` so that the last acknowledgements land.
    expect(r.snapshotsSent).toBeLessThanOrEqual(Math.ceil((120_000 + 50_000) / 5_000) + 2);
    expect(r.snapshotsSent).toBeGreaterThan(20);
  });
});

describe('commands during a large transfer', () => {
  it('with lanes stay within a round trip of idle; the one-line queue did not', async () => {
    const lanes = await runScenario(scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active', burst: BURST }));
    const fifo = await runScenario(scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active', burst: BURST, fifo: true }));
    const quiet = await runScenario(scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active' }));
    // One round trip is 4 × 40 ms; allow for the batch in flight and jitter.
    expect(lanes.commandMs.p95).toBeLessThanOrEqual(quiet.commandMs.p95 + 80);
    expect(lanes.commandMs.p95).toBeLessThanOrEqual(260);
    expect(fifo.commandMs.p95).toBeGreaterThan(lanes.commandMs.p95 * 2);
    // The transfer itself still arrives: lanes reorder, they do not drop.
    expect(lanes.bytesDown).toBeGreaterThanOrEqual(fifo.bytesDown * 0.9);
  });
});

describe('a poor link (150 ms to Supabase, 60 ms jitter, 1% of parts lost)', () => {
  it('recovers: a lost part drops the tab, which reconnects and resends, and most clicks still land', async () => {
    const r = await runScenario(scenario({ ...base, transport: 'relay', profile: PROFILES.relayPoor, sessions: 5, conversation: 'large', mode: 'active' }));
    expect(r.reconnects).toBeGreaterThan(0);
    expect(r.reconnects).toBeLessThanOrEqual(8);
    expect(r.clicks).toBeGreaterThanOrEqual(18);
    expect(r.firstMs.p50).toBeLessThanOrEqual(1_500);
  });
});

describe('reconnection', () => {
  it('a dropped connection comes back, with the table and the click that was waiting', async () => {
    const r = await runScenario(scenario({ ...relay, sessions: 5, conversation: 'large', mode: 'active', dropAtMs: 60_000 }));
    expect(r.reconnects).toBe(1);
    expect(r.clicks).toBeGreaterThanOrEqual(29);
    expect(r.snapshotsSent).toBeGreaterThan(20);
  });
});
